<template><view class="company-panel"><view v-if="error" class="card">{{error}}<button class="ui-button" v-if="needsCompany" @click="go('enterprise-apply')">查看企业认证</button><text v-if="needsCompany" class="hint">已有邀请码可在下方加入企业。</text><button class="ui-button" :disabled="loading" @click="load(true)">{{loading?'正在查询…':'刷新企业状态'}}</button></view><view class="card"><text class="heading">加入企业</text><input v-model="code" placeholder="粘贴负责人给您的邀请码"/><button class="ui-button" :disabled="busy||!code" @click="act(async()=>{await request('/company/accept','POST',{code});code=''})">确认加入</button></view><template v-if="company"><view class="card"><text class="heading">{{company.name}}</text><view>我的角色：{{roles[company.role]}}</view><button class="ui-button" v-if="company.role!=='finance'" @click="go('business')">去采购商品</button><button class="ui-button" @click="go('company-rebate')">企业采购返利</button><button class="ui-button" @click="go('orders',{channel:'B'})">企业采购订单</button></view><view v-if="company.role==='owner'" class="card"><text class="heading">采购设置</text><input v-model="name" placeholder="企业名称"/><view class="row"><text>下单需要负责人同意</text><switch :checked="approval" @change="approval=$event.detail.value"/></view><button class="ui-button" :disabled="busy" @click="act(()=>request('/company/settings','POST',{name,approvalRequired:approval}))">保存设置</button><text class="hint">开启后，采购员提交申请，您同意后才能确认下单。</text></view><view v-if="company.role==='owner'" class="card"><text class="heading">添加员工</text><picker :range="['采购员','财务']" @change="chooseInviteRole"><view class="input">角色：{{roles[role]}} ›</view></picker><button class="ui-button" :disabled="busy" @click="makeInvite">生成邀请码</button><view v-if="inviteCode"><text class="hint">此邀请码岗位：{{roles[inviteRole]}}</text><text selectable>{{inviteCode}}</text><button class="ui-button" @click="copy">复制邀请码</button><text class="hint">请单独交给该员工，7天内有效，只能使用一次。</text></view><view v-for="m in company.members" :key="m.member_id" class="employee"><view>{{m.nickname}} · {{roles[m.role]}} · {{m.enabled?'可使用':'已暂停'}}</view><picker v-if="m.role!=='owner'" :range="['采购员','财务']" @change="changeRole(m,$event)"><view>调整岗位：{{roles[m.role]}} ›</view></picker><button class="ui-button" v-if="m.role!=='owner'" :disabled="busy" @click="act(()=>request('/company/members/'+m.member_id,'POST',{role:m.role,enabled:!m.enabled}))">{{m.enabled?'暂停使用':'恢复使用'}}</button></view></view><view v-if="company.role==='owner'" class="card"><text class="heading">转交负责人</text><text class="hint">新负责人必须先加入本企业。{{needsHandoverPassword?'验证您的密码':'通过微信验证本人身份'}}后发起，由对方登录接受。</text><picker :range="handoverOptions" range-key="label" @change="handoverTarget=handoverOptions[Number($event.detail.value)].id"><view class="input">{{handoverOptions.find(x=>x.id===handoverTarget)?.label||'选择新负责人'}} ›</view></picker><input v-if="needsHandoverPassword" v-model="handoverPassword" password placeholder="输入您当前的登录密码"/><text v-else-if="!isWechat" class="hint">请在本人已登录的微信小程序中验证并发起转交。</text><button class="ui-button" :disabled="busy||!handoverTarget||(needsHandoverPassword?!handoverPassword:!isWechat)" @click="handover">{{needsHandoverPassword?'发起转交':'微信验证并发起转交'}}</button></view><view v-for="h in company.handover" :key="h.company_id" class="card"><text class="heading">负责人转交待确认</text><view>将由 {{h.target_name}} 接任负责人。</view><button class="ui-button" v-if="company.role!=='owner'" :disabled="busy" @click="answer('accept')">我接受担任负责人</button><button class="ui-button" :disabled="busy" @click="answer('cancel')">取消此次转交</button></view><view class="card"><button class="ui-button" @click="go('company-credit')">查看赊购额度与还款</button><button class="ui-button" v-if="company.role==='owner'||company.role==='finance'" @click="go('company-statement')">核对企业账单</button></view><view class="card"><text class="heading">采购申请</text><text v-if="!company.drafts.length" class="hint">暂无采购申请</text><view v-for="d in company.drafts" :key="d.id" class="employee"><view>申请 {{d.id}} · {{states[d.status]}}</view><view>申请金额 ¥{{money(d.amount)}}</view><view v-for="item in d.items" :key="item.id">{{item.name||'商品 '+item.id}} {{item.spec||''}} × {{item.quantity}}</view><view v-if="d.address" class="hint">收货：{{d.address.name}} · {{d.address.address}}</view><view v-if="d.note">处理说明：{{d.note}}</view><template v-if="company.role==='owner'&&d.status==='pending'"><button class="ui-button" :disabled="busy" @click="decision(d,'approved')">同意采购</button><input v-model="notes[d.id]" placeholder="退回时填写原因"/><button class="ui-button" :disabled="busy" @click="decision(d,'rejected')">退回修改</button></template><button class="ui-button" v-if="d.status==='approved'&&d.member_id===company.viewer_id" :disabled="busy" @click="review(d)">确认最新价格并下单</button><button class="ui-button" v-if="d.order_id" @click="go('orders',{channel:'B'})">查看采购订单</button></view></view></template><view v-if="reviewed" class="confirm"><view class="card"><text class="heading">确认采购金额</text><view>申请时 ¥{{money(reviewed.draft.amount)}}</view><view>当前需支付 ¥{{money(reviewed.quote.amount)}}</view><text class="hint">价格、库存和可用余额以提交时为准。确认后才占库存。</text><button class="ui-button" :disabled="busy" @click="submit">确认下单</button><button class="ui-button" :disabled="busy" @click="reviewed=null">暂不下单</button></view></view></view></template>
<script>
import {refreshOnTick} from '../services/panel-refresh'
import {request,money,notify,go} from '../services/shop.js'
export default {mixins:[refreshOnTick()],data(){return{isWechat:false,company:null,loading:false,error:'',busy:false,name:'',approval:false,code:'',role:'buyer',inviteCode:'',inviteRole:'',inviteVersion:0,handoverPassword:'',handoverTarget:0,notes:{},reviewed:null,roles:{owner:'负责人',buyer:'采购员',finance:'财务'},states:{pending:'等负责人同意',approved:'已同意，请确认下单',rejected:'已退回',ordered:'已下单'}}},computed:{needsCompany(){return /企业认证|邀请|未加入企业/.test(this.error)},needsHandoverPassword(){return this.company?.handoverVerification!=='wechat'},handoverOptions(){return (this.company?.members||[]).filter(m=>m.role!=='owner'&&m.enabled).map(m=>({id:m.member_id,label:m.nickname+'（员工 '+m.member_id+'）'}))}},mounted(){
// #ifdef MP-WEIXIN
this.isWechat=true;
// #endif
this.load()},methods:{request,money,go,chooseInviteRole(e){const role=Number(e.detail.value)===1?'finance':'buyer';if(role!==this.role){this.role=role;this.inviteVersion++;this.inviteCode='';this.inviteRole=''}},changeRole(m,e){this.act(()=>request('/company/members/'+m.member_id,'POST',{role:Number(e.detail.value)===1?'finance':'buyer',enabled:!!m.enabled}))},handover(){this.act(async()=>{try{const body={memberId:this.handoverTarget};if(this.needsHandoverPassword)body.password=this.handoverPassword;else{if(!this.isWechat)throw Error('请在微信小程序中验证本人身份');body.code=await new Promise((resolve,reject)=>uni.login({provider:'weixin',success:r=>r.code?resolve(r.code):reject(Error('未取得微信验证凭证，请重试')),fail:()=>reject(Error('微信验证未完成，请重试'))}));}await request('/company/handover','POST',body)}finally{this.handoverPassword=''}})},answer(action){this.act(()=>request('/company/handover/answer','POST',{action}))},async load(feedback=false){if(this.loading)return;this.loading=true;try{const previous=this.company,current=await request('/company');const nameEdited=previous&&this.name!==previous.name,approvalEdited=previous&&this.approval!==!!previous.approval_required;this.company=current;if(!nameEdited)this.name=current.name;if(!approvalEdited)this.approval=!!current.approval_required;this.error='';if(feedback)uni.showToast({title:'企业状态已更新',icon:'none'})}catch(e){this.error=e.message;if(feedback)notify(e)}finally{this.loading=false}},async act(fn){if(this.busy)return;this.busy=true;try{await fn();await this.load()}catch(e){notify(e)}finally{this.busy=false}},makeInvite(){return this.act(async()=>{const role=this.role,version=++this.inviteVersion;this.inviteCode='';this.inviteRole='';const result=await request('/company/invite','POST',{role});if(version===this.inviteVersion&&role===this.role){this.inviteCode=result.code;this.inviteRole=role}})},copy(){if(this.inviteCode&&this.inviteRole===this.role)uni.setClipboardData({data:this.inviteCode})},decision(d,action){this.act(()=>request('/company/drafts/'+d.id+'/decision','POST',{action,note:this.notes[d.id]||''}))},review(d){this.act(async()=>{this.reviewed={draft:d,quote:await request('/company/drafts/'+d.id+'/quote')}})},submit(){this.act(async()=>{const r=this.reviewed;const o=await request('/company/drafts/'+r.draft.id+'/submit','POST',{expectedAmount:r.quote.amount,expectedRebate:r.quote.rebateUsed||0,expectedWallet:r.quote.walletUsed,expectedPoints:r.quote.pointsUsed});this.reviewed=null;go('cashier',{id:o.id,channel:'B'})})}}}
</script>
<style scoped>
@import '../styles/component-base.css';
.company-panel{padding:16px;font-size:16px}.card{background:var(--shop-surface, #fdfeff);padding:18px;border-radius:12px;margin-bottom:14px;line-height:1.8}.heading{display:block;font-size:20px;font-weight:bold;margin-bottom:10px}input,.input{background:var(--shop-background, #f3f8fb);padding:12px;margin:12px 0;border-radius:8px}button{font-size:16px;margin-top:10px;background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c)}.hint{display:block;color:var(--shop-ink, #28546c);font-size:14px}.employee{border-top:1px solid var(--shop-border, #d5e6ee);margin-top:16px;padding-top:12px}.row{display:flex;justify-content:space-between;align-items:center}.confirm{position:fixed;inset:0;background:#0008;z-index:99;display:flex;align-items:center;padding:20px}.confirm .card{width:100%}input{height:44px;min-height:44px;line-height:44px;padding:0 12px;box-sizing:border-box;width:100%;font-size:14px}.heading{font-size:17px}.hint{font-size:12px}.company-panel{padding:12px;font-size:14px}.heading{font-size:17px}.hint{font-size:12px}button{font-size:14px;min-height:40px;line-height:40px}</style>
